<div class="page-header"><div><h1 class="h3 mb-1">Expenses</h1><p class="text-muted">Track, filter and manage spending.</p></div><?php if(can('expenses.create')):?><a class="action-button action-button--success btn btn-primary" href="<?=url('expenses/create')?>"><i data-feather="plus-circle" aria-hidden="true"></i>Add Expense</a><?php endif;?></div><div class="card"><div class="card-body"><form class="row g-2 mb-3"><div class="col-md-3"><input class="form-control" name="q" value="<?=e($f['q'])?>" placeholder="Search description"></div><div class="col-md-2"><select class="form-select" name="category_id"><option value="" data-icon="layers">All categories</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" data-icon="<?=e($c['display_icon'] ?? $c['icon'] ?? 'tag')?>" <?=selected($f['category_id'],$c['id'])?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><select class="form-select" name="account_id"><option value="" data-icon="briefcase">All accounts</option><?php foreach($accounts as $a):?><option value="<?=$a['id']?>" data-account-type="<?=e($a['type'] ?? '')?>" <?=selected($f['account_id'],$a['id'])?>><?=e($a['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><input type="date" class="form-control" name="from" value="<?=e($f['from'])?>"></div><div class="col-md-2"><input type="date" class="form-control" name="to" value="<?=e($f['to'])?>"></div><div class="col-md-1 d-grid"><button class="action-button action-button--primary btn btn-outline-primary"><i data-feather="filter" aria-hidden="true"></i>Filter</button></div></form><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Date</th><th>Description</th><th>Category</th><th>Account</th><th>Amount</th><th></th></tr></thead><tbody><?php foreach($data['rows'] as $row):?><tr><td><?=e(display_date($row['expense_date']))?></td><td><?=e($row['description'])?></td><td><?=e($row['category_name'])?></td><td><?=e($row['account_name'])?></td><td class="fw-semibold"><?=money($row['amount'])?></td><td class="text-end"><a class="action-button action-button--primary btn btn-sm btn-outline-secondary" href="<?=url('expenses/'.$row['id'])?>"><i data-feather="eye" aria-hidden="true"></i>View</a> <?php if(can('expenses.edit') && (int)$row['user_id']===(int)auth_user()['id']):?><a class="action-button action-button--primary btn btn-sm btn-outline-primary" href="<?=url('expenses/'.$row['id'].'/edit')?>"><i data-feather="edit-3" aria-hidden="true"></i>Edit</a><?php endif;?></td></tr><?php endforeach;?><?php if(!$data['rows']):?><tr><td colspan="6" class="text-center text-muted py-5">No expenses found.</td></tr><?php endif;?></tbody></table></div><?php $total=$data['total'];$page=$data['page'];$per=$data['per']; require dirname(__DIR__).'/partials/pagination.php'; ?></div></div>
